\title{The $L^p$ Relaxation of the KNRS Local-Density Conjecture:\\
Sharp Thresholds and the Failure of the Edge-Count Formula}
\author{Aristotle}
\date{July 13, 2026}

\begin{document}
\begin{abstract}
The Kohayakawa--Nagle--R\"odl--Schacht (KNRS) conjecture predicts that a
$\rho$-locally dense host graph contains at least the random count $\rho^{e(F)}$ of
copies of every fixed pattern $F$. We study a one-parameter \emph{$L^p$ relaxation}
of this statement, in which each edge is weighted by an exponent $p>0$ and the
resulting functional is renormalized by a $p$-th root. For each pattern this defines a
critical exponent $p^\star(F)$ below which $\rho$-locally dense counterexamples exist
and above which none do. A clean candidate formula, $p^\star(F)=\binom{n}{2}/m$ (with
$n$ the number of non-isolated vertices and $m$ the number of edges), was proposed by
analogy. We prove that for the single edge $K_2$ this formula is exactly correct
($p^\star(K_2)=1$, sharp on both sides), but that it fails in general: for the two-edge
matching $M_2$ it predicts $3$, whereas the true threshold is $1$. The mechanism is a
factorization $\Lp{W_{M_2}}=\Lp{W_{K_2}}^2$ reducing the matching to a single edge. We
then identify the correct block-construction threshold $(n-c)/m$, with $c$ the number of
connected components, prove $(n-c)/m\le\binom{n}{2}/m$, and show the gap is unbounded
over the matching family.
\end{abstract}

\maketitle

\section{Introduction}

\subsection{Local density and the KNRS conjecture}
A \emph{graphon} is a symmetric measurable function $W:[0,1]^2\to[0,1]$, thought of as a
limit of dense weighted adjacency matrices. We call $W$ \emph{$\rho$-locally dense} if
every measurable $S\subseteq[0,1]$ carries at least its proportional share of weight:
\[
\int_{S\times S} W(x,y)\,dx\,dy \;\ge\; \rho\,|S|^2 .
\]
The Kohayakawa--Nagle--R\"odl--Schacht conjecture asserts that this local condition alone
forces the random abundance of every fixed pattern $F$:
\[
t(F,W):=\int_{[0,1]^{V(F)}} \prod_{\{i,j\}\in E(F)} W(x_i,x_j)\,\prod_{i\in V(F)} dx_i
\;\ge\; \rho^{\,e(F)} .
\]

\subsection{The $L^p$ relaxation}
For $p>0$ define the \emph{$L^p$ pattern norm}
\[
\Lp{W_F}^{\,p} := \int_{[0,1]^{V(F)}} \prod_{\{i,j\}\in E(F)} W(x_i,x_j)^{p}
\,\prod_{i} dx_i,
\qquad
\Lp{W_F} := \big(\Lp{W_F}^{\,p}\big)^{1/p}.
\]
At $p=1$ this is $t(F,W)$; decreasing $p$ rewards spreading weight and makes
$\Lp{W_F}<\rho^{e(F)}$ easier. Let $p^\star(F)$ be the supremum of exponents $p$ for
which a $\rho$-locally dense graphon $W$ (valued in $[0,1]$, some $\rho\in(0,\tfrac12]$)
achieves $\Lp{W_F}<\rho^{e(F)}$.

\subsection{The candidate formula and our results}
Reasoning that $\binom{n}{2}$ edges could be packed onto the $n$ non-isolated vertices,
one is led to the guess $p^\star(F)\stackrel{?}{=}\binom{n}{2}/m$. We show this is exact
for $K_2$ but false in general, and identify the corrected threshold $(n-c)/m$.

\begin{remark}
To keep every integral a finite, rigorous sum we work in the standard finite
step-graphon model: $[0,1]$ is replaced by $N$ equal blocks $\{0,\dots,N-1\}$ under the
uniform measure, and a graphon by a symmetric kernel $W:\{0,\dots,N-1\}^2\to\R$. All
functionals become finite averages.
\end{remark}

\section{The finite model and basic definitions}

\begin{definition}[local density]
A symmetric kernel $W:\{0,\dots,N-1\}^2\to\R$ is \emph{$\rho$-locally dense} if
$\rho|S|^2\le\sum_{i\in S}\sum_{j\in S}W(i,j)$ for every $S\subseteq\{0,\dots,N-1\}$.
\end{definition}

\begin{definition}[single-edge functional]
$\displaystyle \Lp{W_{K_2}}^{\,p}=\frac{1}{N^2}\sum_{i,j}W(i,j)^p$, and
$\Lp{W_{K_2}}=\big(\Lp{W_{K_2}}^{\,p}\big)^{1/p}$.
\end{definition}

\begin{definition}[two-edge-matching functional]
$\displaystyle \Lp{W_{M_2}}^{\,p}=\frac{1}{N^4}\sum_{a,b,c,d}W(a,b)^p\,W(c,d)^p$, and
$\Lp{W_{M_2}}=\big(\Lp{W_{M_2}}^{\,p}\big)^{1/p}$.
\end{definition}

\section{The single edge: the formula is exact}
Here $n=2$, $m=1$, $e(K_2)=1$, and $\binom{2}{2}/1=1$.

\begin{theorem}[upper region]\label{thm:edge-upper}
Let $N\ge1$ and let $W\ge0$ be $\rho$-locally dense. Then for every $p\ge1$,
$\Lp{W_{K_2}}\ge\rho$.
\end{theorem}
\begin{proof}[Proof sketch]
Local density on $S=\{0,\dots,N-1\}$ gives $\rho\le\frac{1}{N^2}\sum_{i,j}W(i,j)$, the
arithmetic mean of $W$. The weighted power-mean inequality with uniform weights $1/N^2$
gives, for $p\ge1$, $\text{arithmetic mean}\le(\text{mean of }W^p)^{1/p}=\Lp{W_{K_2}}$.
Chain the two.
\end{proof}

Fix $N=2$ and define the two-block kernel
$\blockrho(i,j)=2\rho$ if $i=j$ and $0$ otherwise.

\begin{lemma}[validity]\label{lem:block-valid}
If $0\le\rho$ and $2\rho\le1$ then $\blockrho$ is valued in $[0,1]$ and $\rho$-locally
dense.
\end{lemma}
\begin{proof}[Proof sketch]
Values are $0$ or $2\rho\in[0,1]$. For $S\subseteq\{0,1\}$ only diagonal entries
contribute, so $\sum_{i,j\in S}\blockrho(i,j)=2\rho|S|\ge\rho|S|^2$ since $|S|\le2$.
\end{proof}

A direct evaluation yields $\Lp{\blockrho{}_{,K_2}}^{\,p}=\tfrac12(2\rho)^p$, whence
$\Lp{\blockrho{}_{,K_2}}=\rho\cdot 2^{\,1-1/p}$.

\begin{theorem}[lower region]\label{thm:edge-lower}
For every $\rho>0$ and every $0<p<1$, $\Lp{\blockrho{}_{,K_2}}=\rho\cdot 2^{1-1/p}<\rho$.
\end{theorem}
\begin{proof}[Proof sketch]
The exponent $1-\tfrac1p<0$ for $p<1$, so $2^{1-1/p}<1$. Equivalently
$\tfrac12(2\rho)^p=2^{p-1}\rho^p<\rho^p$ because $2^p<2$; take $p$-th roots.
\end{proof}

\begin{theorem}[sharpness]\label{thm:edge-sharp}
For $0<\rho\le\tfrac12$: no counterexample exists for $p\ge1$
(Theorem~\ref{thm:edge-upper}), and $\blockrho$ is one for every $0<p<1$
(Lemma~\ref{lem:block-valid}, Theorem~\ref{thm:edge-lower}). Hence $p^\star(K_2)=1$.
\end{theorem}

\section{The two-edge matching: the formula fails}
For $M_2$, $n=4$, $m=2$, $e(M_2)=2$, so $\binom{4}{2}/2=3$.

\begin{theorem}[factorization]\label{thm:factor}
For every kernel $W$ and $p>0$, $\Lp{W_{M_2}}^{\,p}=\big(\Lp{W_{K_2}}^{\,p}\big)^2$; and
if $W\ge0$, $\Lp{W_{M_2}}=\Lp{W_{K_2}}^2$.
\end{theorem}
\begin{proof}[Proof sketch]
The summand factors over the disjoint index pairs:
$\sum_{a,b,c,d}W(a,b)^pW(c,d)^p=\big(\sum_{a,b}W(a,b)^p\big)\big(\sum_{c,d}W(c,d)^p\big)$,
and $1/N^4=(1/N^2)^2$. Take $(1/p)$-th powers.
\end{proof}

\begin{theorem}[disproof of $\binom{n}{2}/m$]\label{thm:disproof}
Let $N\ge1$ and $W\ge0$ be $\rho$-locally dense with $\rho\ge0$. Then for every $p\ge1$,
$\Lp{W_{M_2}}\ge\rho^2=\rho^{e(M_2)}$. In particular no counterexample exists on
$1\le p<3$, contradicting the formula's prediction of counterexamples for all $p<3$.
\end{theorem}
\begin{proof}[Proof sketch]
By Theorem~\ref{thm:factor}, $\Lp{W_{M_2}}=\Lp{W_{K_2}}^2$; by
Theorem~\ref{thm:edge-upper}, $\Lp{W_{K_2}}\ge\rho\ge0$ for $p\ge1$; square.
\end{proof}

\begin{theorem}[sharpness for $M_2$]\label{thm:m2-sharp}
For $0<\rho\le\tfrac12$ and $0<p<1$, $\blockrho$ satisfies
$\Lp{\blockrho{}_{,M_2}}<\rho^2$. With Theorem~\ref{thm:disproof}, $p^\star(M_2)=1$.
\end{theorem}
\begin{proof}[Proof sketch]
$\Lp{\blockrho{}_{,M_2}}=\Lp{\blockrho{}_{,K_2}}^2$ and the inner norm is
$\rho\cdot2^{1-1/p}<\rho$ by Theorem~\ref{thm:edge-lower}; square.
\end{proof}

\section{The corrected threshold: connectivity, not vertex count}

Partition the vertices into $k$ equal blocks and set $W_k(x,y)=k\rho$ if $x,y$ lie in the
same block and $0$ otherwise.

\begin{proposition}[local density of block kernels]\label{prop:block-ld}
For $0\le\rho$ and $k\rho\le1$, $W_k$ is a graphon valued in $[0,1]$ and $\rho$-locally
dense.
\end{proposition}
\begin{proof}[Proof sketch]
If $S$ meets block $b$ in mass $s_b$ then $\int_{S\times S}W_k=k\rho\sum_b s_b^2\ge
k\rho\,(\sum_b s_b)^2/k=\rho|S|^2$ by Cauchy--Schwarz.
\end{proof}

\begin{proposition}[block functional]\label{prop:block-val}
Let $F$ have $n$ non-isolated vertices, $m$ edges and $c$ components. Then
$\Lp{W_{k,F}}^{\,p}=k^{\,c-n+mp}\rho^{mp}$ and $\Lp{W_{k,F}}=\rho^{\,m}k^{\,m-(n-c)/p}$.
\end{proposition}
\begin{proof}[Proof sketch]
A vertex assignment contributes nonzero only if it is constant on each component; there
are $k^{c}$ such assignments, each with normalization $k^{-n}$ and value $(k\rho)^{mp}$.
Multiply and take the $(1/p)$-th power.
\end{proof}

\begin{theorem}[block-construction threshold]\label{thm:corrected}
For every pattern $F$ and every $p<(n-c)/m$ there are $\rho$-locally dense graphons with
$\Lp{W_F}<\rho^{e(F)}$; hence $p^\star(F)\ge(n-c)/m$. Moreover
$(n-c)/m\le\binom{n}{2}/m$, with the two equal for $K_2$ and $M_2$ but differing by
$2k-2$ for the matching $M_k$ (where $(n-c)/m=1$ while $\binom{2k}{2}/k=2k-1$).
\end{theorem}
\begin{proof}[Proof sketch]
From Proposition~\ref{prop:block-val}, $\Lp{W_{k,F}}<\rho^m$ iff $m-(n-c)/p<0$ iff
$p<(n-c)/m$ (for $k\ge2$); let $k\to\infty$. Finally $n-c\le n-1\le\binom{n}{2}$.
\end{proof}

\section{Discussion and future directions}

The single edge and every matching have true threshold $1$, governed by the number of
independent binding constraints $n-c$ (the rank of a spanning forest), not by the count
$\binom{n}{2}$ of possible edges. The failure of the naive formula is a concrete warning
against guessing thresholds from crude vertex/edge counts when a pattern decomposes into
vertex-disjoint pieces.

\begin{enumerate}
\item \textbf{Exact threshold.} Is $p^\star(F)=(n-c)/m$ for all $F$? First test: the
triangle $K_3$ ($n=3,m=3,c=1$), where block kernels give $p<2/3$; is there a
counterexample for $2/3\le p<1$, or any for $p\ge1$?
\item \textbf{Rank-one perturbations.} Kernels $W=\rho+c\,\varphi(x)\varphi(y)$ with
$c\ge0$ are automatically $\rho$-locally dense and far more flexible than block kernels;
compute their $L^p$ functional.
\item \textbf{General block theorem.} Establish
$\frac{1}{N^n}\sum_\varphi\prod_{\text{edges}}W(\varphi)^p=k^{c-n+mp}\rho^{mp}$ for
arbitrary $F$ and map the block-achievable region for all patterns.
\end{enumerate}

\begin{center}
\begin{tabular}{lccccccc}
\toprule
Pattern & $n$ & $m$ & $c$ & $\binom{n}{2}/m$ & $(n-c)/m$ & proven $p^\star$\\
\midrule
Edge $K_2$ & 2 & 1 & 1 & $1$ & $1$ & $1$ (exact)\\
Matching $M_2$ & 4 & 2 & 2 & $3$ & $1$ & $1$ (exact)\\
Matching $M_k$ & $2k$ & $k$ & $k$ & $2k-1$ & $1$ & $1$ (exact)\\
Triangle $K_3$ & 3 & 3 & 1 & $1$ & $2/3$ & open in $[2/3,1]$\\
\bottomrule
\end{tabular}
\end{center}

