from __future__ import annotations
from typing import List

Kernel = List[List[float]]

def two_block_kernel(rho: float) -> Kernel:
    """2*rho on the diagonal blocks, 0 off-diagonal."""
    return [[2.0 * rho if i == j else 0.0 for j in range(2)] for i in range(2)]

def edge_lp(W: Kernel, p: float) -> float:
    n = len(W)
    total = sum(W[i][j] ** p for i in range(n) for j in range(n))
    return (total / n ** 2) ** (1.0 / p)

def demo() -> None:
    rho = 0.4
    W = two_block_kernel(rho)
    print("single edge K2: closed form rho*2^(1-1/p)")
    for p in [0.25, 0.5, 0.75, 1.0, 2.0]:
        val = edge_lp(W, p)
        print(f"p={p:>4}: ||W_K2||={val:.6f}  ({'< rho' if val < rho else '>= rho'})")

if __name__ == "__main__":
    demo()

from __future__ import annotations
from itertools import product
from typing import List

Kernel = List[List[float]]

def two_block_kernel(rho: float) -> Kernel:
    return [[2.0 * rho if i == j else 0.0 for j in range(2)] for i in range(2)]

def edge_lp(W: Kernel, p: float) -> float:
    n = len(W)
    return (sum(W[i][j] ** p for i in range(n) for j in range(n)) / n ** 2) ** (1.0 / p)

def matching_lp(W: Kernel, p: float) -> float:
    n = len(W)
    tot = 0.0
    for a, b, c, d in product(range(n), repeat=4):
        tot += (W[a][b] ** p) * (W[c][d] ** p)
    return (tot / n ** 4) ** (1.0 / p)

def demo() -> None:
    rho = 0.4
    W = two_block_kernel(rho)
    print("matching M2: naive threshold C(4,2)/2 = 3, but true threshold = 1")
    for p in [0.5, 1.0, 2.0]:
        m2, e2 = matching_lp(W, p), edge_lp(W, p) ** 2
        print(f"p={p}: ||W_M2||={m2:.6f}  edge^2={e2:.6f}  rho^2={rho**2:.4f}")

if __name__ == "__main__":
    demo()

from __future__ import annotations
from math import comb
from typing import List, Tuple

def k_block_norm(k: int, rho: float, p: float, n: int, m: int, c: int) -> float:
    """Closed form rho^m * k^{m - (n-c)/p}."""
    return rho ** m * k ** (m - (n - c) / p)

def thresholds(n: int, m: int, c: int) -> Tuple[float, float]:
    return comb(n, 2) / m, (n - c) / m

def demo() -> None:
    pats: List[Tuple[str, int, int, int]] = [
        ("K2", 2, 1, 1), ("M2", 4, 2, 2), ("M3", 6, 3, 3), ("K3", 3, 3, 1)]
    for name, n, m, c in pats:
        naive, corrected = thresholds(n, m, c)
        print(f"{name}: naive={naive:.3f} corrected={corrected:.3f} gap={naive-corrected:.3f}")

if __name__ == "__main__":
    demo()

