function IS_LOCALLY_DENSE(W, rho):
    N <- number of rows of W
    for mask in 0 .. 2^N - 1:
        S <- { i : bit i of mask is 1 }
        total <- sum of W[i][j] for i in S, j in S
        if total < rho * |S|^2:
            return False
    return True

function PATTERN_LP_NORM(W, edges, k_vertices, p):
    N <- size of W;  total <- 0
    for phi in all maps {0..k-1} -> {0..N-1}:
        prod <- 1
        for (u, v) in edges:
            prod <- prod * W[phi[u]][phi[v]]^p
        total <- total + prod
    return (total / N^k)^(1/p)

